import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        final long MOD = 1000000007L;
        int n = nextInt(), d = nextInt();
        long[] v = new long[26];
        Arrays.fill(v, 1);
        long[] p = new long[27];
        for (int step = 1; step < n; step++) {
            for (int i = 0; i < 26; i++) p[i + 1] = (p[i] + v[i]) % MOD;
            for (int i = 0; i < 26; i++) v[i] = (p[Math.min(26, i + d + 1)] - p[Math.max(0, i - d)] + MOD) % MOD;
        }
        long s = 0;
        for (long x : v) s = (s + x) % MOD;
        System.out.println(s);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	const MOD = 1000000007
	n, d := int(nextInt()), int(nextInt())
	v := make([]int64, 26)
	for i := range v {
		v[i] = 1
	}
	p := make([]int64, 27)
	for step := 1; step < n; step++ {
		for i := 0; i < 26; i++ {
			p[i+1] = (p[i] + v[i]) % MOD
		}
		for i := 0; i < 26; i++ {
			v[i] = (p[min(26, i+d+1)] - p[max(0, i-d)] + MOD) % MOD
		}
	}
	var s int64
	for _, x := range v {
		s = (s + x) % MOD
	}
	fmt.Println(s)
}
